DELETE FROM mall_product WHERE id IN

    #{id}

AND product_type = 'drug'

mapper.select:
SELECT
,
(SELECT COUNT(*) FROM shopping_cart sc WHERE sc.product_id = p.id) AS subscription_count
FROM mall_product p

    p.product_type = 'drug'

        AND p.id = #{id}


        AND (p.name LIKE concat('%',#{name},'%')
             OR p.generic_name LIKE concat('%',#{name},'%'))


        AND p.medical_category = #{category}


        AND p.is_otc = #{isOtc}


        AND p.status = #{status}


ORDER BY p.id DESC

    LIMIT #{current},#{size}

SELECT COUNT(*)
FROM mall_product p

    p.product_type = 'drug'

        AND p.id = #{id}


        AND (p.name LIKE concat('%',#{name},'%')
             OR p.generic_name LIKE concat('%',#{name},'%'))


        AND p.medical_category = #{category}


        AND p.is_otc = #{isOtc}


        AND p.status = #{status}

mapper.insert:
INSERT INTO shopping_cart (user_id, product_id, quantity)
VALUES (#{userId}, #{drugId}, #{quantity})
ON DUPLICATE KEY UPDATE quantity = #{quantity}
